const body = $json.body || {};
const headers = $json.headers || {};
const normalizedHeaders = Object.fromEntries(
  Object.entries(headers).map(([key, value]) => [String(key).toLowerCase(), value]),
);
const auth = normalizedHeaders.authorization || "";
const headerToken =
  normalizedHeaders["x-karina-admin-token"] ||
  "";
const token = String(headerToken || auth.replace(/^Bearer\s+/i, "")).trim();
const expected = "bbd113f07683e8c16d30b058bc1184fa4ed943c9b1dcc99edacee843fd31c0a0";
const placeholderValue = "CHANGE" + "_ME_ADMIN_TOKEN";
const debugRequested = body.debug === true;

function sqlString(value) {
  return String(value ?? "").replace(/'/g, "''");
}

function phoneDigits(value) {
  return String(value ?? "").replace(/\D/g, "");
}

function uuidV4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(char) {
    const random = Math.random() * 16 | 0;
    const value = char === "x" ? random : (random & 0x3 | 0x8);
    return value.toString(16);
  });
}

if (!expected || expected === placeholderValue || token !== expected) {
  return [{
    json: {
      ok: false,
      statusCode: 401,
      response: {
        ok: false,
        error: "unauthorized",
        ...(debugRequested ? {
          debug: {
            expectedConfigured: Boolean(expected && expected !== placeholderValue),
            hasCustomTokenHeader: Boolean(headerToken),
            hasAuthorizationHeader: Boolean(auth),
            tokenMatchesExpected: Boolean(token && expected && token === expected),
            headerKeys: Object.keys(headers).sort(),
          },
        } : {}),
      },
    },
  }];
}

const action = String(body.action || "summary");
let sql = "";

if (action === "summary") {
  sql = `
SELECT jsonb_build_object(
  'users_total', (SELECT COUNT(*) FROM users),
  'subscriptions_status_active', (SELECT COUNT(*) FROM subscriptions WHERE status = 'active'),
  'messages_total', (SELECT COUNT(*) FROM whatsapp_mensasagens),
  'chat_history_rows', (SELECT COUNT(*) FROM n8n_chat_histories),
  'chat_history_sessions', (SELECT COUNT(DISTINCT session_id) FROM n8n_chat_histories)
) AS payload;
`;
}

if (action === "users") {
  sql = `
SELECT COALESCE(jsonb_agg(row_to_json(row_data) ORDER BY row_data.last_interaction_at DESC NULLS LAST), '[]'::jsonb) AS payload
FROM (
  SELECT
    u.phone,
    COALESCE(u.frist_name, u.name, '') AS frist_name,
    u.name,
    u.public_id,
    u.last_interaction_at,
    u.status,
    s.id AS subscription_id,
    COALESCE(s.status, 'inactive') AS subscription_status,
    s.valid_until
  FROM users u
  LEFT JOIN LATERAL (
    SELECT id, status, valid_until
    FROM subscriptions s
    WHERE s.user_phone = u.phone
    ORDER BY s.updated_at DESC NULLS LAST, s.created_at DESC NULLS LAST
    LIMIT 1
  ) s ON true
  ORDER BY u.last_interaction_at DESC NULLS LAST
  LIMIT 300
) row_data;
`;
}

if (action === "messages") {
  const phone = phoneDigits(body.phone);
  if (!phone) {
    return [{ json: { ok: false, statusCode: 400, response: { ok: false, error: "phone_required" } } }];
  }
  sql = `
SELECT COALESCE(jsonb_agg(row_to_json(row_data) ORDER BY row_data.created_at DESC), '[]'::jsonb) AS payload
FROM (
  SELECT numero, created_at, "from", origem, mensagem_texto, mensagem_tipo
  FROM whatsapp_mensasagens
  WHERE numero = '${sqlString(phone)}'
  ORDER BY created_at DESC
  LIMIT 150
) row_data;
`;
}

if (action === "memorySummary") {
  const phone = phoneDigits(body.phone);
  if (!phone) {
    return [{ json: { ok: false, statusCode: 400, response: { ok: false, error: "phone_required" } } }];
  }
  sql = `
SELECT jsonb_build_object(
  'phone_exists_in_users', EXISTS (SELECT 1 FROM users WHERE phone = '${sqlString(phone)}'),
  'whatsapp_message_count', (SELECT COUNT(*) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}'),
  'whatsapp_user_count', (SELECT COUNT(*) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}' AND "from" = 'user'),
  'whatsapp_agent_count', (SELECT COUNT(*) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}' AND "from" = 'Agente'),
  'whatsapp_api_origin_count', (SELECT COUNT(*) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}' AND origem = 'API'),
  'whatsapp_uazapi_origin_count', (SELECT COUNT(*) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}' AND origem = 'uazapi'),
  'latest_whatsapp_at', (SELECT MAX(created_at) FROM whatsapp_mensasagens WHERE numero = '${sqlString(phone)}'),
  'chat_history_rows', (SELECT COUNT(*) FROM n8n_chat_histories WHERE session_id = '${sqlString(phone)}'),
  'chat_history_session_exists', EXISTS (SELECT 1 FROM n8n_chat_histories WHERE session_id = '${sqlString(phone)}')
) AS payload;
`;
}

if (action === "toggleAccess") {
  const phone = phoneDigits(body.phone);
  const status = String(body.status || "");
  if (!phone || !["active", "inactive", "canceled", "expired"].includes(status)) {
    return [{ json: { ok: false, statusCode: 400, response: { ok: false, error: "invalid_toggle_payload" } } }];
  }
  const subscriptionId = uuidV4();
  sql = `
WITH updated AS (
  UPDATE subscriptions
  SET status = '${sqlString(status)}', updated_at = now()
  WHERE user_phone = '${sqlString(phone)}'
  RETURNING id, user_phone, status, valid_until
),
inserted AS (
  INSERT INTO subscriptions (id, user_phone, gateway, status, currency, created_at, updated_at)
  SELECT '${sqlString(subscriptionId)}'::uuid, '${sqlString(phone)}', 'manual', '${sqlString(status)}', 'BRL', now(), now()
  WHERE NOT EXISTS (SELECT 1 FROM updated)
  RETURNING id, user_phone, status, valid_until
)
SELECT row_to_json(result)::jsonb AS payload
FROM (
  SELECT * FROM updated
  UNION ALL
  SELECT * FROM inserted
  LIMIT 1
) result;
`;
}

if (action === "selfTestAccessNoop") {
  sql = `
WITH insert_probe AS (
  INSERT INTO subscriptions (id, user_phone, gateway, status, currency, created_at, updated_at)
  SELECT '00000000-0000-4000-8000-000000000000'::uuid, '900000000000', 'admin_api_self_test', 'inactive', 'BRL', now(), now()
  WHERE false
  RETURNING id
),
update_probe AS (
  UPDATE subscriptions
  SET status = status, updated_at = updated_at
  WHERE false
  RETURNING id
),
delete_probe AS (
  DELETE FROM subscriptions
  WHERE false
  RETURNING id
)
SELECT jsonb_build_object(
  'insert_probe_rows', (SELECT COUNT(*) FROM insert_probe),
  'update_probe_rows', (SELECT COUNT(*) FROM update_probe),
  'delete_probe_rows', (SELECT COUNT(*) FROM delete_probe),
  'mutated_rows', (
    (SELECT COUNT(*) FROM insert_probe) +
    (SELECT COUNT(*) FROM update_probe) +
    (SELECT COUNT(*) FROM delete_probe)
  ),
  'permissions_probe_ok', true
) AS payload;
`;
}

if (!sql) {
  return [{ json: { ok: false, statusCode: 400, response: { ok: false, error: "unknown_action" } } }];
}

return [{ json: { ok: true, action, sql } }];

const action = $("Build Request").first().json.action;
const row = $input.first().json || {};
const payload = row.payload;

if (action === "summary") return [{ json: { ok: true, summary: payload || {} } }];
if (action === "users") return [{ json: { ok: true, users: payload || [] } }];
if (action === "messages") return [{ json: { ok: true, messages: payload || [] } }];
if (action === "memorySummary") return [{ json: { ok: true, memorySummary: payload || {} } }];
if (action === "toggleAccess") return [{ json: { ok: true, access: payload || null } }];
if (action === "selfTestAccessNoop") return [{ json: { ok: true, selfTest: payload || null } }];

return [{ json: { ok: false, error: "unknown_action" } }];
